    stopTw();
    if (state.twEl) state.twEl.textContent = state.twText;
    elDropCaret();
    if (state.twDone) { const d = state.twDone; state.twDone = null; d(); }
  }
  function stopTw() {
    if (state.twTimer) { clearInterval(state.twTimer); state.twTimer = null; }
