  // ---- 酒馆助手接口封装（特性检测 + 降级） ----
  const TH = {
    hasVars: function () { return typeof getVariables === 'function'; },
    hasAssign: function () { return typeof insertOrAssignVariables === 'function'; },
    hasCreateMsg: function () { return typeof createChatMessages === 'function'; },
    hasSlash: function () { return typeof triggerSlash === 'function'; },
    readChatVars: async function () {
      if (!this.hasVars()) return null;
      try { return (await getVariables({ type: 'chat' })) || null; } catch (e) { return null; }
    },
    writeChatVars: async function (payload) {
      if (!this.hasAssign()) throw new Error('酒馆助手 insertOrAssignVariables 不可用');
      await insertOrAssignVariables(payload, { type: 'chat' });
    },
    sendAssistantMessage: async function (message) {
      if (this.hasCreateMsg()) {
        await createChatMessages([{ role: 'assistant', message: message }], { insert_before: 'end' });
        return 'createChatMessages';
      }
      if (this.hasSlash()) {
        // 降级：/sendas 以角色名义发送（换行会被压平，属尽力而为的旧版兼容路径）
        await triggerSlash('/sendas name=' + state.name + ' ' + message.split('\n').join(' '));
        return 'triggerSlash';
      }
      throw new Error('酒馆助手消息接口不可用（createChatMessages / triggerSlash 均未检测到）');
    },
  };

  /* ====================================================================
   * 写入链路（一次性，确认时执行；每步幂等可安全重试）
   *   1. $mms_portrait_choice     → MiniMapStatus 立绘选择
   *   2. rpg_combat_roster        → RpgCombat 英雄档案（version 1 结构）
   *   3. createChatMessages       → AI 角色开场白落楼（含立绘标签 + Status_block）
   *   4. $opening_setup_done      → 本组件幂等标记
   * ==================================================================== */

  function buildHeroSave() {
    const base = OPENING_DATA.identity.baseConfig;
    const p = portraitEntry();
    const cfg = Object.assign({}, base);
    cfg.img = (p &amp;&amp; p.url) ? p.url : null;
    return {
      name: state.name,
      config: cfg,
      skills: skillEntries().map(function (e) { return Object.assign({}, e.data); }),
      items: itemEntries().map(function (e) { return Object.assign({}, e.data); }),
    };
  }

  function buildItemsString(entries) {
    if (!entries.length) return '无';
    return '[💼] ' + entries.map(function (e) {
      const c = e.data.count || 0;
      return '[' + e.data.name + (c > 1 ? 'x' + c : '') + ']';
    }).join('');
  }
  function buildWeaponsString(entries) {
    const weapons = entries.filter(function (e) { return e.data.category === '武器'; });
    if (!weapons.length) return '无';
    return '[🔪] ' + weapons.map(function (e) { return '[' + e.data.name + ']'; }).join('');
  }

  function buildStatusBlock() {
    const lines = [];
    lines.push('状态栏:');
    lines.push('  日期和时间: "' + OPENING_DATA.status.date + '"');
    lines.push('  地点: "' + OPENING_DATA.status.place + '"');
    lines.push('  角色列表:');
    lines.push('    - 角色:');
    lines.push('        名字: "' + OPENING_DATA.identity.emoji + state.name + '"');
    lines.push('        属性: "' + OPENING_DATA.identity.attrs + '"');
    lines.push('        穿着: "' + OPENING_DATA.identity.wearing + '"');
    lines.push('        内心: "' + OPENING_DATA.identity.inner + '"');
    lines.push('        武器: "' + buildWeaponsString(itemEntries()) + '"');
    lines.push('        物品: "' + buildItemsString(itemEntries()) + '"');
    if (OPENING_DATA.status.allies.length || OPENING_DATA.status.npcs.length) {
      lines.push('  人物:');
      lines.push('    盟友: ' + JSON.stringify(OPENING_DATA.status.allies));
      lines.push('    NPC: ' + JSON.stringify(OPENING_DATA.status.npcs));
    }
    lines.push('  行动选项:');
    lines.push('    名字: "🧑 ' + state.name + '"');
    lines.push('    选项:');
    OPENING_DATA.status.options.forEach(function (o) { lines.push('      - "' + o + '"'); });
    return '<Status_block>\n' + lines.join('\n') + '\n</Status_block>';
  }

  function buildOpeningMessage() {
    const narrative = fill(OPENING_DATA.openingTemplate, {
      名字: state.name,
      技能清单: listNames(skillEntries()),
      物品清单: listNames(itemEntries()),
    });
    const portraitTag = state.portrait ? '【立绘 ' + state.portrait + '】' : '';
    return narrative + '\n\n' + portraitTag + '\n\n' + buildStatusBlock();
  }

  function buildDoneFlag() {
    return {
      ts: Date.now(),
      name: state.name,
      portrait: state.portrait,
      skills: skillEntries().map(function (e) { return e.data.name; }),
      items: itemEntries().map(function (e) { return e.data.name; }),
    };
  }

  async function submitAll() {
    if (state.submitting) return;
    state.submitting = true;
    state.stage = 'loading';
    state.progress = 0;
    state.stepRows = [];
    render();

    const steps = [
      ['立绘选择同步 · MiniMapStatus', async function () {
        if (!state.portrait) return;
        await TH.writeChatVars({ $mms_portrait_choice: state.portrait });
      }],
      ['战斗档案写入 · RpgCombat', async function () {
        await TH.writeChatVars({ rpg_combat_roster: { version: 1, heroes: [buildHeroSave()] } });
      }],
      ['开场白以 AI 角色身份注入聊天流', async function () {
        if (state.openingSent) return; // 重试时防重复落楼
        await TH.sendAssistantMessage(buildOpeningMessage());
        state.openingSent = true;
      }],
      ['归档标记写入', async function () {
        await TH.writeChatVars({ $opening_setup_done: buildDoneFlag() });
      }],
    ];

    try {
      for (let i = 0; i < steps.length; i++) {
        state.stepRows.push({ label: steps[i][0], status: 'run' });
        renderLoading();
        await steps[i][1]();
        state.stepRows[i].status = 'ok';
        state.progress = Math.round(((i + 1) / steps.length) * 100);
        renderLoading();
      }
      state.stage = 'done';
      render();
    } catch (err) {
      state.submitting = false;
      state.errorMsg = (err &amp;&amp; err.message) || String(err);
      state.stage = 'error';
      render();
    }
  }

