      + '  <div class="mt-8 flex items-center justify-between w-full max-w-xl">'
      + '    <button class="btn-ghost" data-action="back-portrait">返回</button>'
      + '    <button class="btn-noir" data-action="confirm-submit" id="submit-btn">签署委托书</button>'
      + '  </div>'
      + (state.flash ? '<div class="flash-warn mt-3">' + esc(state.flash) + '</div>' : '')
      + '</div>';
  }

  function loadingBody() {
    const rows = (state.stepRows || []).map(function (r) {
      const mark = r.status === 'ok' ? '<span class="text-[#7fae7f]">✓</span>' : '<span class="text-[#d9b45c] tw-caret"> </span>';
      return '<div class="flex items-center gap-3 py-1.5 text-sm tracking-[0.12em]">' + mark + '<span class="' + (r.status === 'ok' ? 'text-[rgba(232,220,192,0.55)]' : 'text-[#e8dcc0]') + '">' + esc(r.label) + '</span></div>';
    }).join('');
    return '<div class="progress-track mb-5"><div class="progress-fill" style="width:' + (state.progress || 0) + '%"></div></div>' + rows;
  }

  function viewLoading() {
    return ''
      + '<div class="min-h-screen flex flex-col items-center justify-center px-6 py-14">'
      + header('PROCESSING · 正在归档', '档案誊写中')
      + '  <div class="glass max-w-md w-full px-8 py-8 fade-in" id="loading-body">' + loadingBody() + '</div>'
      + '</div>';
  }

  function viewDone() {
    return ''
      + '<div class="min-h-screen flex flex-col items-center justify-center px-6 py-14">'
      + header('FILED · 归档完成', '故事开始')
      + '  <div class="glass max-w-xl w-full px-8 py-8 text-center fade-in">'
      + '    <div class="stamp mb-6">档案已归档</div>'
      + '    <div class="text-sm text-[rgba(232,220,192,0.85)] leading-loose">'
      + '      <p>' + esc(state.name) + ' 的开场白已以 AI 角色身份注入聊天流，</p>'
      + '      <p>状态栏将随开场白一同渲染，立绘与战斗档案均已写入。</p>'
      + '    </div>'
      + '    <div class="mt-6 font-tw text-[0.7rem] text-[rgba(198,161,84,0.65)] tracking-wider">请关闭本界面，向下滚动查看开场楼 · 本向导重新打开时将显示归档摘要</div>'
      + '  </div>'
      + '</div>';
  }

  function viewArchived() {
    const d = state.doneFlag || {};
    const rows = function (label, val) {
      return '<div class="flex gap-3 py-1.5 tw-line"><span class="text-[rgba(44,36,22,0.6)] text-xs tracking-[0.25em] w-24 shrink-0 pt-0.5">' + esc(label) + '</span><span class="text-sm leading-relaxed">' + esc(val) + '</span></div>';
    };
    return ''
      + '<div class="min-h-screen flex flex-col items-center justify-center px-6 py-14">'
      + header('FILED · 已初始化', '档案摘要')
      + '  <div class="paper max-w-xl w-full px-9 py-8 fade-in">'
      + '    <div class="flex items-center justify-between mb-4">'
      + '      <div class="font-black tracking-[0.4em] text-lg">归档摘要</div>'
      + '      <div class="stamp text-xs">已建档</div>'
      + '    </div>'
      + rows('时间', d.ts ? fmtTs(d.ts) : '—')
      + rows('姓名', d.name || '—')
      + rows('技能', (d.skills &amp;&amp; d.skills.length) ? d.skills.join('、') : '（无）')
      + rows('物品', (d.items &amp;&amp; d.items.length) ? d.items.join('、') : '（无）')
      + rows('立绘', d.portrait || '（默认）')
      + '    <div class="mt-6 text-[0.7rem] text-[rgba(44,36,22,0.55)] leading-relaxed">本聊天已完成开场初始化，向导不会重复执行。如需重开新档：新开聊天，或在酒馆助手变量管理中删除聊天变量 $opening_setup_done 后刷新。</div>'
      + '  </div>'
      + '  <div class="mt-6"><button class="btn-ghost" data-action="force-redo">强制重新配置（覆盖写入）</button></div>'
      + '</div>';
  }

  function viewError() {
    return ''
      + '<div class="min-h-screen flex flex-col items-center justify-center px-6 py-14">'
      + header('ERROR · 归档受阻', '写入失败')
      + '  <div class="glass max-w-xl w-full px-8 py-8 fade-in" style="border-color:rgba(160,48,48,0.55)">'
      + '    <div class="text-sm text-[rgba(232,220,192,0.85)] leading-relaxed mb-4">写入过程中出现问题；已完成的步骤幂等，可直接重试：</div>'
      + '    <div class="font-tw text-[0.75rem] text-[#d98c8c] bg-[rgba(0,0,0,0.35)] rounded p-3 break-all">' + esc(state.errorMsg || '未知错误') + '</div>'
      + '    <div class="mt-6 text-right"><button class="btn-noir" data-action="retry">重试</button></div>'
      + '  </div>'
      + '</div>';
  }

  /* ==================== 事件 ==================== */

  app.addEventListener('click', function (ev) {
    const t = ev.target.closest('[data-action]');
    if (!t) return;
    const act = t.getAttribute('data-action');
    switch (act) {
      case 'tw-skip':
        if (state.twTimer) finishTw();
        break;
      case 'sound': toggleSound(); break;
      case 'start':
        state.stage = 'story'; state.storyPage = 0; render(); break;
      case 'story-next':
        state.storyPage++; render(); break;
      case 'story-done':
        state.stage = 'identity'; render(); break;
      case 'identity-done':
        state.stage = 'skills'; render(); break;
      case 'skill-toggle': toggleSkill(t.getAttribute('data-skill-id')); break;
      case 'skills-done':
        if (!state.selectedSkills.size) { state.flash = '至少选定一项技能'; render(); break; }
        state.flash = ''; state.stage = 'items'; render(); break;
      case 'item-toggle': toggleItem(t.getAttribute('data-item-id')); break;
      case 'items-done': state.stage = 'portrait'; render(); break;
      case 'portrait-pick':
        state.portrait = t.getAttribute('data-portrait-key') || ''; render(); break;
      case 'portrait-done': state.stage = 'confirm'; render(); break;
      case 'confirm-submit': submitAll(); break;
      case 'retry': state.stage = 'loading'; state.stepRows = []; state.progress = 0; submitAll(); break;
      case 'force-redo':
        state.stage = 'title'; state.openingSent = false; state.doneFlag = null; render(); break;
      case 'back-identity': state.stage = 'identity'; render(); break;
      case 'back-skills': state.stage = 'skills'; render(); break;
      case 'back-items': state.stage = 'items'; render(); break;
      case 'back-portrait': state.stage = 'portrait'; render(); break;
    }
  });

  function toggleSound() {
    state.soundOn = !state.soundOn;
    try {
      bgVideo.muted = !state.soundOn;
      if (OPENING_DATA.bgm.url) {
        if (!bgm.src) bgm.src = OPENING_DATA.bgm.url;
        bgm.volume = 0.55;
        if (state.soundOn) { bgm.play(); } else { bgm.pause(); }
      }
    } catch (e) { /* 自动播放策略拒绝时静默 */ }
    render();
  }

  function refreshBudget(boxId, used, total) {
    const box = document.getElementById(boxId);
    if (box) box.innerHTML = budgetBar(used, total, false);
  }

  function toggleSkill(id) {
    const entry = OPENING_DATA.skills.find(function (e) { return e.id === id; });
    if (!entry) return;
    if (state.selectedSkills.has(id)) { state.selectedSkills.delete(id); }
    else {
      if (skillsUsed() + entry.shopCost > OPENING_DATA.shop.skillPoints) {
        refreshBudget('skill-budget', skillsUsed(), OPENING_DATA.shop.skillPoints);
        return; // 点数不足：拒绝选中（预算边界）
      }
      state.selectedSkills.add(id);
    }
    render();
  }

  function toggleItem(id) {
    const entry = OPENING_DATA.items.find(function (e) { return e.id === id; });
    if (!entry) return;
    if (state.selectedItems.has(id)) { state.selectedItems.delete(id); }
    else {
      if (itemsUsed() + entry.shopCost > OPENING_DATA.shop.itemPoints) {
        refreshBudget('item-budget', itemsUsed(), OPENING_DATA.shop.itemPoints);
        return;
      }
      state.selectedItems.add(id);
    }
    render();
  }

  /* ==================== 启动 ==================== */

  async function boot() {
    // 背景视频 / BGM 配置应用
    if (OPENING_DATA.bgVideo.url) {
      bgVideo.src = OPENING_DATA.bgVideo.url;
      bgVideo.classList.remove('hidden');
      bgVideo.style.setProperty('--vid-op', String(OPENING_DATA.bgVideo.opacity || 0.6));
      bgFallback.style.display = 'none';
    }

    // 幂等检查：本聊天已初始化 → 归档摘要，不再进向导
    const vars = await TH.readChatVars();
    const done = vars ? vars.$opening_setup_done : null;
    if (done &amp;&amp; typeof done === 'object') {
      state.doneFlag = done;
      state.stage = 'archived';
    } else {
      state.stage = 'title';
    }
    render();
  }

  // 调试/测试钩子（MMS window.MMS 同款惯例，不影响产品行为）
  window.__OPENING_DEBUG__ = { state: state, DATA: OPENING_DATA, instant: false };

  boot();
})();
</script>
</body>
</html>

